+	var wg sync.WaitGroup
+	for _, target := range targets {
+		target := target
+		wg.Add(1)
+		go func() {
+			defer wg.Done()
+			isPrimary := target.Repo.CommonDir == primary
+			if err := runBindingReplayHook(ctx, target.Repo.WorktreeRoot, agentName, hookName, payload, isPrimary); err != nil {
